'use client';

import * as React from 'react';
import {createComponent, type EventName} from '@lit/react';
import '@material/web/labs/gb/components/chip/md-gb-chip.js';
import '@material/web/labs/gb/components/chip/md-gb-chip-set.js';
import {ChipElement} from '@material/web/labs/gb/components/chip/chip-element.js';
import {ChipSetElement} from '@material/web/labs/gb/components/chip/chip-set-element.js';

/**
 * A Material Design Expressive Chip component. Wraps <md-gb-chip>.
 * Docs: https://material-web.dev/3.0/components/chip/
 */
export const MdChip = createComponent({
  react: React,
  tagName: 'md-gb-chip',
  elementClass: ChipElement,
  events: {
    onChange: 'change' as EventName<Event>,
    onEdit: 'edit' as EventName<CustomEvent>,
    onInput: 'input' as EventName<InputEvent>,
    onRemove: 'remove' as EventName<Event>,
    onUpdateFocus: 'update-focus' as EventName<Event>,
  },
});

export type MdChipProps = React.ComponentProps<typeof MdChip>;

/**
 * A Material Design Expressive chip set. Wraps <md-gb-chip-set>.
 * Docs: https://material-web.dev/3.0/components/chip/
 */
export const MdChipSet = createComponent({
  react: React,
  tagName: 'md-gb-chip-set',
  elementClass: ChipSetElement,
});

export type MdChipSetProps = React.ComponentProps<typeof MdChipSet>;
